from hashlib import sha256
from html import unescape
from pathlib import Path
from urllib.request import Request, urlopen
import re

URL = "https://www.w3.org/TR/2006/REC-xml-20060816/"
SOURCE_SHA256 = "a520bc8c34a6ae9a6b9f80440f0edc5d017c8562f6ec259d3888f2a2a3520021"
HEX = re.compile(r"#x([0-9A-Fa-f]+)(?:-#x([0-9A-Fa-f]+))?")

def source_ranges(html, production):
    start = html.index(f'id="NT-{production}"')
    end = html.find('id="NT-', start + 1)
    block = html[start:end if end >= 0 else None]
    return [(int(a, 16), int(b or a, 16)) for a, b in HEX.findall(block)]

def code_ranges(source, table):
    start = source.index(f"const {table}:")
    end = source.index("\n];", start)
    return [(int(a, 16), int(b, 16)) for a, b in re.findall(
        r"\(0x([0-9A-Fa-f]+),\s*0x([0-9A-Fa-f]+)\)", source[start:end]
    )]

def expand(ranges):
    result = set()
    for start, end in ranges:
        result.update(range(start, end + 1))
    return result

def sorted_disjoint(ranges):
    return all(start <= end for start, end in ranges) and all(
        left_end < right_start
        for (_, left_end), (right_start, _) in zip(ranges, ranges[1:])
    )

raw = urlopen(Request(URL, headers={"User-Agent": "litchi-spec-gaps-names-evidence/1.0"}), timeout=30).read()
assert sha256(raw).hexdigest() == SOURCE_SHA256
html = unescape(raw.decode("utf-8"))
source = Path("crates/litchi-ods/src/codec/formula/expression/names.rs").read_text()
checks = {
    "LETTER_RANGES": source_ranges(html, "BaseChar") + source_ranges(html, "Ideographic"),
    "COMBINING_RANGES": source_ranges(html, "CombiningChar"),
    "DIGIT_RANGES": source_ranges(html, "Digit"),
}
for table, production in checks.items():
    actual = code_ranges(source, table)
    expected_points = expand(production)
    actual_points = expand(actual)
    print(table, len(expected_points), len(actual_points), len(production), len(actual))
    assert actual_points == expected_points
    assert sorted_disjoint(actual)
